def _exact_json_value(value: object, expected: object) -> bool:
    """Compare generated JSON values without bool/int/float coercion."""

    if type(value) is not type(expected):
        return False
    if isinstance(expected, dict):
        return set(value) == set(expected) and all(
            _exact_json_value(value[name], expected[name]) for name in expected
        )
    if isinstance(expected, list):
        return len(value) == len(expected) and all(
            _exact_json_value(item, expected_item)
            for item, expected_item in zip(value, expected, strict=True)
        )
    return value == expected


def _runner_path() -> Path | None:
    module_path = Path(__file__).resolve()
    source_root = module_path.parents[2]
    if source_root.name == "python":
        source_runner = source_root.parent / "scripts/tune_greedy_tail.py"
        if source_runner.is_file():
            return source_runner
    packaged_runner = module_path.with_name("tune_greedy_tail.py")
    return packaged_runner if packaged_runner.is_file() else None


def _compile_helper_path() -> Path | None:
    module_path = Path(__file__).resolve()
    source_root = module_path.parents[2]
    if source_root.name == "python":
        compile_helper = (
            source_root.parent / "scripts/precompile/cubin_bundles.py"
        )
        if compile_helper.is_file():
            return compile_helper
    return None


