def _sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _canonical_json_sha256(value: object) -> str:
    encoded = json.dumps(value, sort_keys=True, separators=(",", ":")).encode()
    return hashlib.sha256(encoded).hexdigest()


def _runtime_launcher_provider_path() -> Path:
    from kestrel_kernels import cubin_runtime

    return Path(cubin_runtime.__file__).resolve()


def greedy_tail_runtime_launch_contract_sha256(
    source: str | None = None,
) -> str:
    """Hash the callable executed inside candidate CUDA-event timing.

    Dispatch resolution, cubin loading, and packed archive decoding finish
    before the tuner enters its timed operation.  Selected shipping validation
    independently reruns those paths for correctness, so including them here
    would incorrectly invalidate retained candidate timings.
    """

    if source is None:
        payload = semantic_python_symbol_closure_bytes(
            _runtime_launcher_provider_path(),
            _RUNTIME_LAUNCH_CONTRACT_IDENTITY_SYMBOLS,
        )
    else:
        payload = semantic_python_symbol_closure_source_bytes(
            source,
            _RUNTIME_LAUNCH_CONTRACT_IDENTITY_SYMBOLS,
        )
    return hashlib.sha256(payload).hexdigest()


def greedy_tail_packed_runtime_contract_sha256(
    source: str | None = None,
) -> str:
    """Hash packed decode, resolution, receipt, and launch construction."""

    if source is None:
        payload = semantic_python_symbol_closure_bytes(
            _runtime_launcher_provider_path(),
            _PACKED_RUNTIME_CONTRACT_IDENTITY_SYMBOLS,
        )
    else:
        payload = semantic_python_symbol_closure_source_bytes(
            source,
            _PACKED_RUNTIME_CONTRACT_IDENTITY_SYMBOLS,
        )
    return hashlib.sha256(payload).hexdigest()


def greedy_tail_native_tensor_launcher_implementation_sha256(
    source: str | None = None,
) -> str:
    """Hash the complete native bridge that loads and launches packed cubins."""

    if source is None:
        provider = _native_launcher_provider_path()
        if provider is None:
            raise RuntimeError("native tensor launcher source is unavailable")
        return _sha256(provider)
    return hashlib.sha256(source.encode("utf-8")).hexdigest()


def _native_launcher_embedded_identity() -> str | None:
    """Return the source identity embedded in an installed native bridge."""

    spec = importlib.util.find_spec("kestrel_kernels._pybridge")
    origin = "" if spec is None else str(spec.origin or "")
    native_installed = any(
        origin.endswith(suffix)
        for suffix in importlib.machinery.EXTENSION_SUFFIXES
    )
    try:
        pybridge = importlib.import_module("kestrel_kernels._pybridge")
    except ImportError as exc:
        if native_installed:
            raise RuntimeError(
                "native tensor launcher source identity is unavailable"
            ) from exc
        return None
    module_path = str(getattr(pybridge, "__file__", ""))
    if not any(
        module_path.endswith(suffix)
        for suffix in importlib.machinery.EXTENSION_SUFFIXES
    ):
        return None
    source_sha256 = getattr(pybridge, "_source_sha256", None)
    if not callable(source_sha256):
        raise RuntimeError("native tensor launcher source identity is unavailable")
    identity = source_sha256()
    if (
        not isinstance(identity, str)
        or re.fullmatch(r"[0-9a-f]{64}", identity) is None
    ):
        raise RuntimeError("native tensor launcher source identity is malformed")
    return identity


def _available_shipping_source_identities() -> dict[str, str]:
    identities = {
        "packed_runtime_contract_sha256": (
            greedy_tail_packed_runtime_contract_sha256()
        )
    }
    packer = _packer_path()
    if packer is not None:
        identities["packer_sha256"] = _semantic_provider_identity(
            packer, ("pack_kstlc",)
        )
    provider = _native_launcher_provider_path()
    embedded_identity = _native_launcher_embedded_identity()
    if provider is not None:
        identities["native_tensor_launcher_implementation_sha256"] = (
            greedy_tail_native_tensor_launcher_implementation_sha256()
        )
        if (
            embedded_identity is not None
            and embedded_identity
            != identities["native_tensor_launcher_implementation_sha256"]
        ):
            raise RuntimeError("native tensor launcher binary is stale for its source")
    elif embedded_identity is not None:
        identities["native_tensor_launcher_implementation_sha256"] = embedded_identity
    elif sys.platform != "darwin":
        raise RuntimeError("native tensor launcher source identity is unavailable")
    return identities


def _available_source_paths() -> dict[str, Path]:
    paths = {
        "config_module_sha256": Path(__file__),
        "kernel_sha256": Path(__file__).with_name("greedy_tail.py"),
    }
    for name, path in (
        ("runner_sha256", _runner_path()),
        ("packer_sha256", _packer_path()),
        ("device_compile_contract_sha256", _compile_helper_path()),
        ("compile_provider_sha256", _compile_provider_path()),
    ):
        if path is not None:
            paths[name] = path
    return paths


def _semantic_provider_identity(path: Path | None, symbols: tuple[str, ...]) -> str:
    if path is None:
        raise RuntimeError("greedy-tail semantic source provider is unavailable")
    return hashlib.sha256(
        semantic_python_symbol_closure_bytes(path, symbols)
    ).hexdigest()


def _kernel_identity() -> str:
    return _semantic_provider_identity(
        Path(__file__).with_name("greedy_tail.py"), _KERNEL_IDENTITY_SYMBOLS
    )


def _fake_tensor_provider_identity() -> str:
    provider = _fake_tensor_provider_path()
    if provider is None:
        raise RuntimeError("greedy-tail fake tensor provider is unavailable")
    source = semantic_python_symbols_bytes(provider, ("make_fake_tensor",))
    return hashlib.sha256(source).hexdigest()


def _available_source_identities() -> dict[str, dict[str, str]]:
    paths = _available_source_paths()
    semantic_identities = {
        "config_module_sha256": _CONFIG_MODULE_IDENTITY_SYMBOLS,
        "kernel_sha256": _KERNEL_IDENTITY_SYMBOLS,
        "runner_sha256": _RUNNER_IDENTITY_SYMBOLS,
        "packer_sha256": ("pack_kstlc",),
        "device_compile_contract_sha256": ("_compile_cubin_device_contract",),
        "compile_provider_sha256": _COMPILE_PROVIDER_IDENTITY_SYMBOLS,
    }
    flat = {
        name: _semantic_provider_identity(path, semantic_identities[name])
        for name, path in paths.items()
    }
    flat["runtime_launch_contract_sha256"] = (
        greedy_tail_runtime_launch_contract_sha256()
    )
    if _fake_tensor_provider_path() is not None:
        flat["fake_tensor_provider_sha256"] = (
            _fake_tensor_provider_identity()
        )
    shipping = _available_shipping_source_identities()
    return {
        "timing_contract": {
            name: flat[name]
            for name in _B200_TIMING_SOURCE_IDENTITIES
            if name in flat
        },
        "shipping_correctness_contract": {
            name: shipping[name]
            for name in _SHIPPING_SOURCE_IDENTITIES
            if name in shipping
        },
    }


def _validate_source_identity_shape(source: object) -> None:
    if not isinstance(source, Mapping) or set(source) != _SOURCE_CONTRACT_SECTIONS:
        raise RuntimeError("greedy-tail authority source identities are incomplete")
    for section, expected in (
        ("timing_contract", _B200_TIMING_SOURCE_IDENTITIES),
        ("shipping_correctness_contract", _SHIPPING_SOURCE_IDENTITIES),
    ):
        values = source[section]
        if not isinstance(values, Mapping) or set(values) != expected:
            raise RuntimeError("greedy-tail authority source identities are incomplete")
        if any(
            not isinstance(value, str)
            or re.fullmatch(r"[0-9a-f]{64}", value) is None
            for value in values.values()
        ):
            raise RuntimeError("greedy-tail authority source identity is malformed")


def _validate_source_identities(source: object) -> None:
    _validate_source_identity_shape(source)
    assert isinstance(source, Mapping)
    available = _available_source_identities()
    identities = available["timing_contract"]
    if any(
        source["timing_contract"][name] != value
        for name, value in identities.items()
    ):
        raise RuntimeError("greedy-tail authority timing contract is stale")


def _validate_shipping_source_identities(source: Mapping[str, object]) -> None:
    available = _available_shipping_source_identities()
    shipping = source["shipping_correctness_contract"]
    assert isinstance(shipping, Mapping)
    if any(shipping[name] != value for name, value in available.items()):
        raise RuntimeError("greedy-tail shipping correctness contract is stale")


def _validate_toolchain_shape(toolchain: object) -> Mapping[str, object]:
    if not isinstance(toolchain, Mapping) or set(toolchain) != _TOOLCHAIN_IDENTITIES:
        raise RuntimeError("greedy-tail authority toolchain identity is incomplete")
    if any(
        not isinstance(toolchain[name], str) or not toolchain[name]
        for name in _EXPECTED_TOOLCHAIN
    ) or (
        not isinstance(toolchain["cuda_driver_version"], int)
        or isinstance(toolchain["cuda_driver_version"], bool)
        or toolchain["cuda_driver_version"] <= 0
    ):
        raise RuntimeError("greedy-tail authority toolchain identity is malformed")
    return toolchain


def _validate_toolchain(toolchain: object) -> None:
    toolchain = _validate_toolchain_shape(toolchain)
    differences = {
        name: {"expected": expected, "observed": toolchain[name]}
        for name, expected in _EXPECTED_TOOLCHAIN.items()
        if toolchain[name] != expected
    }
    if differences:
        raise RuntimeError(
            "greedy-tail authority compiler toolchain is unsupported: "
            f"{json.dumps(differences, sort_keys=True)}"
        )


def _validate_shipping_toolchain(toolchain: object) -> None:
    """Validate the ABI/compiler surface used to refresh shipped kernels."""

    toolchain = _validate_toolchain_shape(toolchain)
    python_series = str(toolchain["python"]).split(".")[:2]
    expected_python_series = _EXPECTED_TOOLCHAIN["python"].split(".")[:2]
    differences = {
        name: {"expected": expected, "observed": toolchain[name]}
        for name, expected in _EXPECTED_TOOLCHAIN.items()
        if name != "python" and toolchain[name] != expected
    }
    if python_series != expected_python_series:
        differences["python_series"] = {
            "expected": ".".join(expected_python_series),
            "observed": ".".join(python_series),
        }
    if differences:
        raise RuntimeError(
            "greedy-tail shipping toolchain is incompatible: "
            f"{json.dumps(differences, sort_keys=True)}"
        )


def _portable_sample_stdev(samples: list[float]) -> float:
    exact = [Fraction.from_float(value) for value in samples]
    if len(exact) < 2:
        raise ValueError("sample stdev needs at least two values")
    mean = sum(exact, start=Fraction()) / len(exact)
    variance = sum(
        ((value - mean) ** 2 for value in exact),
        start=Fraction(),
    ) / (len(exact) - 1)
    # statistics.stdev used platform sqrt before Python 3.11 and can differ by
    # one ULP. Exact variance plus excess Decimal precision is stable here.
    with localcontext() as context:
        context.prec = 80
        decimal_variance = Decimal(variance.numerator) / Decimal(
            variance.denominator
        )
        return float(decimal_variance.sqrt())


def derive_greedy_tail_summary(samples: list[float]) -> dict[str, float | int]:
    ordered = sorted(float(value) for value in samples)
    if len(ordered) != 9 or any(
        not math.isfinite(value) or value <= 0.0 for value in ordered
    ):
        raise ValueError("greedy-tail timing summary needs nine positive samples")
    return {
        "count": len(ordered),
        "min_us": ordered[0],
        "p25_us": ordered[len(ordered) // 4],
        "median_us": statistics.median(ordered),
        "p75_us": ordered[(3 * len(ordered)) // 4],
        "max_us": ordered[-1],
        "mean_us": statistics.fmean(ordered),
        "stdev_us": _portable_sample_stdev(ordered),
    }


def _positive_samples(value: object, *, count: int, label: str) -> list[float]:
    if not isinstance(value, list) or len(value) != count:
        raise RuntimeError(f"greedy-tail authority {label} has incomplete samples")
    samples = []
    for item in value:
        if type(item) is not float:
            raise RuntimeError(f"greedy-tail authority {label} sample is malformed")
        sample = item
        if not math.isfinite(sample) or sample <= 0.0:
            raise RuntimeError(f"greedy-tail authority {label} sample is invalid")
        samples.append(sample)
    return samples


def _validate_timing_evidence(
    *,
    samples_value: object,
    independent_runs_value: object,
    summary_value: object,
    label: str,
) -> list[float]:
    samples = _positive_samples(samples_value, count=9, label=label)
    if not isinstance(independent_runs_value, list) or len(
        independent_runs_value
    ) != 9:
        raise RuntimeError(
            f"greedy-tail authority {label} lacks independent timing runs"
        )
    independent_runs = [
        _positive_samples(run, count=3, label=f"{label} run")
        for run in independent_runs_value
    ]
    if samples != [statistics.median(run) for run in independent_runs]:
        raise RuntimeError(
            f"greedy-tail authority {label} samples are not raw-run medians"
        )
    if not _exact_json_value(summary_value, derive_greedy_tail_summary(samples)):
        raise RuntimeError(
            f"greedy-tail authority {label} summary is not derived"
        )
    return samples


def _validate_correctness(value: object, *, label: str) -> None:
    if not isinstance(value, Mapping) or set(value) != set(
        GREEDY_TAIL_REQUIRED_CASES
    ) or any(value[case] is not True for case in GREEDY_TAIL_REQUIRED_CASES):
        raise RuntimeError(f"greedy-tail authority {label} correctness is incomplete")


def _candidate_identity(threads: int, splits: int) -> str:
    return f"t{threads}_s{splits}"


def _validate_candidate(
    identity: str, candidate: object, *, expected: tuple[int, int], capacity: int
) -> None:
    if not isinstance(candidate, Mapping) or set(candidate) != {
        "threads",
        "splits",
        "correctness",
        "samples_us",
        "independent_run_samples_us",
        "summary",
    }:
        raise RuntimeError(
            f"greedy-tail authority B{capacity} candidate {identity!r} is incomplete"
        )
    threads, splits = expected
    if (
        identity != _candidate_identity(threads, splits)
        or type(candidate["threads"]) is not int
        or type(candidate["splits"]) is not int
        or candidate["threads"] != threads
        or candidate["splits"] != splits
    ):
        raise RuntimeError(
            f"greedy-tail authority B{capacity} candidate identity is malformed"
        )
    _validate_correctness(candidate["correctness"], label=identity)
    _validate_timing_evidence(
        samples_value=candidate["samples_us"],
        independent_runs_value=candidate["independent_run_samples_us"],
        summary_value=candidate["summary"],
        label=identity,
    )


def _validate_batch_evidence(
    capacity: int,
    batch_row: object,
    *,
    kernel_sha256: str,
    build_toolchain_sha256: str,
    require_shipping_toolchain: bool,
) -> tuple[Mapping[str, Mapping[str, Any]], Mapping[str, Any]]:
    if not isinstance(batch_row, Mapping) or set(batch_row) != {
        "baseline",
        "candidates",
        "selection",
        "shipping_path_validation",
    }:
        raise RuntimeError(f"greedy-tail authority B{capacity} evidence is incomplete")
    candidates = batch_row["candidates"]
    expected_candidates = {
        _candidate_identity(threads, splits): (threads, splits)
        for threads, splits in GREEDY_TAIL_SEARCH_SPACE[capacity]
    }
    if not isinstance(candidates, Mapping) or set(candidates) != set(
        expected_candidates
    ):
        raise RuntimeError(
            f"greedy-tail authority B{capacity} lacks complete candidate coverage"
        )
    for identity, expected in expected_candidates.items():
        _validate_candidate(
            identity, candidates[identity], expected=expected, capacity=capacity
        )

    baseline = batch_row["baseline"]
    if not isinstance(baseline, Mapping) or set(baseline) != {
        "identity",
        "samples_us",
        "independent_run_samples_us",
        "summary",
    } or baseline["identity"] != "torch_argmax_plus_index_copy":
        raise RuntimeError(f"greedy-tail authority B{capacity} baseline is incomplete")
    _validate_timing_evidence(
        samples_value=baseline["samples_us"],
        independent_runs_value=baseline["independent_run_samples_us"],
        summary_value=baseline["summary"],
        label=f"B{capacity} baseline",
    )

    selection = batch_row["selection"]
    if not isinstance(selection, Mapping):
        raise RuntimeError(f"greedy-tail authority B{capacity} selection is incomplete")
    derived = derive_greedy_tail_selection(candidates)
    if not _exact_json_value(selection, derived):
        raise RuntimeError(
            f"greedy-tail authority B{capacity} selection is not derived"
        )

    shipping = batch_row["shipping_path_validation"]
    expected_shipping_keys = {
        "identity",
        "direct_correctness",
        "packed_correctness",
        "packed_artifact",
        "shipping_samples_us",
        "shipping_independent_run_samples_us",
        "shipping_summary",
        "direct_tvm_ffi_samples_us",
        "direct_tvm_ffi_independent_run_samples_us",
        "direct_tvm_ffi_summary",
        "torch_baseline_samples_us",
        "torch_baseline_independent_run_samples_us",
        "torch_baseline_summary",
        "shipping_over_direct_ratio",
        "packed_over_torch_ratio",
        "promotion_rule",
        "promoted",
    }
    accepted_shipping_keys = (expected_shipping_keys,)
    with_shipping_toolchain = expected_shipping_keys | {"shipping_toolchain"}
    if require_shipping_toolchain:
        accepted_shipping_keys = (with_shipping_toolchain,)
    else:
        accepted_shipping_keys += (with_shipping_toolchain,)
    if (
        not isinstance(shipping, Mapping)
        or set(shipping) not in accepted_shipping_keys
        or shipping["identity"] != derived["identity"]
    ):
        raise RuntimeError(
            f"greedy-tail authority B{capacity} shipping validation is incomplete"
        )
    _validate_correctness(
        shipping["direct_correctness"], label=f"B{capacity} direct"
    )
    _validate_correctness(
        shipping["packed_correctness"], label=f"B{capacity} packed"
    )
    packed_artifact = shipping["packed_artifact"]
    if not isinstance(packed_artifact, Mapping) or set(packed_artifact) != {
        "archive_sha256",
        "archive_size_bytes",
        "payload_sha256",
        "receipt",
    }:
        raise RuntimeError(
            f"greedy-tail authority B{capacity} packed identity is incomplete"
        )
    shipping_toolchain = shipping.get("shipping_toolchain")
    if shipping_toolchain is not None:
        _validate_shipping_toolchain(shipping_toolchain)
        build_toolchain_sha256 = _canonical_json_sha256(shipping_toolchain)
    receipt = packed_artifact["receipt"]
    receipt_keys = {
        "schema_version",
        "family",
        "variant_key",
        "architecture",
        "manifest_content_fingerprint",
        "inventory_fingerprint",
        "payload_kind",
        "payload_sha256",
        "archive_size_bytes",
        "archive_sha256",
        "archive_root",
    }
    sha_fields = (
        packed_artifact["archive_sha256"],
        packed_artifact["payload_sha256"],
    )
    if (
        type(packed_artifact["archive_size_bytes"]) is not int
        or packed_artifact["archive_size_bytes"] <= 0
        or any(
            not isinstance(value, str)
            or re.fullmatch(r"[0-9a-f]{64}", value) is None
            for value in sha_fields
        )
        or not isinstance(receipt, Mapping)
        or not receipt_keys <= set(receipt)
        or not set(receipt) <= receipt_keys | {
            "source_fingerprint",
            "build_toolchain_sha256",
        }
        or type(receipt["schema_version"]) is not int
        or receipt["schema_version"] != 1
        or receipt["family"] != "softmax_greedy"
        or receipt["variant_key"]
        != greedy_tail_variant_key(GREEDY_TAIL_VOCAB_SIZE, capacity)
        or receipt["architecture"] != "sm100"
        or receipt["payload_kind"] != "cubin"
        or receipt["archive_root"] != "cu13"
        or receipt["archive_sha256"] != packed_artifact["archive_sha256"]
        or receipt["archive_size_bytes"]
        != packed_artifact["archive_size_bytes"]
        or receipt["payload_sha256"] != packed_artifact["payload_sha256"]
        or any(
            not isinstance(receipt[name], str)
            or re.fullmatch(r"[0-9a-f]{64}", receipt[name]) is None
            for name in (
                "manifest_content_fingerprint",
                "inventory_fingerprint",
            )
        )
        or any(
            not isinstance(receipt[name], str)
            or re.fullmatch(r"[0-9a-f]{64}", receipt[name]) is None
            for name in ("source_fingerprint", "build_toolchain_sha256")
            if name in receipt
        )
    ):
        raise RuntimeError(
            f"greedy-tail authority B{capacity} packed identity is malformed"
        )
    if (
        receipt.get("source_fingerprint", kernel_sha256) != kernel_sha256
        or receipt.get("build_toolchain_sha256", build_toolchain_sha256)
        != build_toolchain_sha256
    ):
        raise RuntimeError(
            f"greedy-tail authority B{capacity} packed identity is not cross-linked"
        )
    shipping_samples = _validate_timing_evidence(
        samples_value=shipping["shipping_samples_us"],
        independent_runs_value=shipping["shipping_independent_run_samples_us"],
        summary_value=shipping["shipping_summary"],
        label=f"B{capacity} shipping",
    )
    direct_samples = _validate_timing_evidence(
        samples_value=shipping["direct_tvm_ffi_samples_us"],
        independent_runs_value=(
            shipping["direct_tvm_ffi_independent_run_samples_us"]
        ),
        summary_value=shipping["direct_tvm_ffi_summary"],
        label=f"B{capacity} direct",
    )
    torch_samples = _validate_timing_evidence(
        samples_value=shipping["torch_baseline_samples_us"],
        independent_runs_value=(
            shipping["torch_baseline_independent_run_samples_us"]
        ),
        summary_value=shipping["torch_baseline_summary"],
        label=f"B{capacity} torch baseline",
    )
    ratio = shipping["shipping_over_direct_ratio"]
    if (
        type(ratio) is not float
        or ratio
        != statistics.median(shipping_samples) / statistics.median(direct_samples)
    ):
        raise RuntimeError(
            f"greedy-tail authority B{capacity} shipping ratio is not derived"
        )
    packed_over_torch_ratio = shipping["packed_over_torch_ratio"]
    derived_packed_over_torch_ratio = (
        statistics.median(shipping_samples) / statistics.median(torch_samples)
    )
    promotion_rule = (
        "median(packed_samples_us) < median(torch_baseline_samples_us)"
    )
    if (
        type(packed_over_torch_ratio) is not float
        or packed_over_torch_ratio != derived_packed_over_torch_ratio
        or shipping["promotion_rule"] != promotion_rule
        or type(shipping["promoted"]) is not bool
        or shipping["promoted"] != (derived_packed_over_torch_ratio < 1.0)
        or shipping["promoted"] is not True
    ):
        raise RuntimeError(
            f"greedy-tail authority B{capacity} packed promotion is not derived"
        )
    return candidates, derived


def derive_greedy_tail_selection(
    candidates: Mapping[str, Mapping[str, Any]],
) -> dict[str, Any]:
    """Derive one capacity winner from raw, correctness-gated samples."""

    if not candidates:
        raise ValueError("greedy-tail authority has no candidates")
    derived: dict[str, dict[str, Any]] = {}
    for identity, candidate in candidates.items():
        threads = int(candidate["threads"])
        splits = int(candidate["splits"])
        samples = [float(value) for value in candidate["samples_us"]]
        if threads <= 0 or splits <= 0 or len(samples) != 9:
            raise ValueError(f"invalid greedy-tail candidate {identity!r}")
        if any(not math.isfinite(value) or value <= 0.0 for value in samples):
            raise ValueError(f"non-finite greedy-tail sample in {identity!r}")
        correctness = candidate.get("correctness")
        if (
            not isinstance(correctness, Mapping)
            or set(correctness) != set(GREEDY_TAIL_REQUIRED_CASES)
            or any(
            correctness.get(case) is not True for case in GREEDY_TAIL_REQUIRED_CASES
            )
        ):
            raise ValueError(
                f"greedy-tail candidate {identity!r} lacks a correctness gate"
            )
        derived[identity] = {
            "threads": threads,
            "splits": splits,
            "median_us": statistics.median(samples),
            "mean_us": statistics.fmean(samples),
            "stdev_us": _portable_sample_stdev(samples),
            "sample_count": len(samples),
        }

    best_median = min(row["median_us"] for row in derived.values())
    tie_band_us = max(0.01, best_median * 0.005)
    median_eligible = {
        identity: row
        for identity, row in derived.items()
        if row["median_us"] <= best_median + tie_band_us
    }
    best_mean = min(row["mean_us"] for row in median_eligible.values())
    mean_tie_band_us = max(0.01, best_mean * 0.005)
    eligible = {
        identity: row
        for identity, row in median_eligible.items()
        if row["mean_us"] <= best_mean + mean_tie_band_us
    }
    # Sub-percent differences are below the calibrated noise gate. Requiring
    # both median and cross-run mean excludes allocation-sensitive outliers;
    # among the remaining ties, prefer less launched work and then fewer CTAs.
    identity = min(
        eligible,
        key=lambda key: (
            eligible[key]["threads"] * eligible[key]["splits"],
            eligible[key]["splits"],
            eligible[key]["threads"],
            key,
        ),
    )
    row = derived[identity]
    return {
        "identity": identity,
        "threads": row["threads"],
        "splits": row["splits"],
        "median_us": row["median_us"],
        "best_median_us": best_median,
        "best_mean_us": best_mean,
        "tie_band_us": tie_band_us,
        "mean_tie_band_us": mean_tie_band_us,
        "eligible_identities": sorted(eligible),
    }


def _validate_greedy_tail_artifact(
    artifact: object,
    *,
    require_current_sources: bool,
    require_shipping_toolchain: bool = True,
) -> tuple[GreedyTailConfig, ...]:
    if not isinstance(artifact, Mapping) or set(artifact) != {
        "schema_version",
        "target",
        "measurement",
        "toolchain",
        "source",
        "batches",
    } or type(artifact.get("schema_version")) is not int or artifact.get(
        "schema_version"
    ) != 1:
        raise RuntimeError("unsupported greedy-tail authority schema")
    target = artifact.get("target")
    if not _exact_json_value(target, {
        "gpu": "NVIDIA B200",
        "capability": [10, 0],
        "vocab_size": GREEDY_TAIL_VOCAB_SIZE,
        "dtype": "bfloat16",
    }):
        raise RuntimeError("greedy-tail authority target is incomplete")
    if not _exact_json_value(artifact.get("measurement"), _EXPECTED_MEASUREMENT):
        raise RuntimeError("greedy-tail authority measurement protocol is incomplete")

    toolchain = artifact.get("toolchain")
    source = artifact.get("source")
    _validate_toolchain(toolchain)
    if require_current_sources:
        _validate_source_identities(source)
    else:
        _validate_source_identity_shape(source)
    assert isinstance(toolchain, Mapping)
    assert isinstance(source, Mapping)

    batches = artifact.get("batches")
    if not isinstance(batches, Mapping) or set(batches) != {
        str(value) for value in GREEDY_TAIL_BATCH_CAPACITIES
    }:
        raise RuntimeError("greedy-tail authority lacks complete batch coverage")
    configs = []
    common_shipping_toolchain: object | None = None
    for capacity in GREEDY_TAIL_BATCH_CAPACITIES:
        batch_row = batches[str(capacity)]
        _candidates, derived = _validate_batch_evidence(
            capacity,
            batch_row,
            kernel_sha256=source["timing_contract"]["kernel_sha256"],
            build_toolchain_sha256=_canonical_json_sha256(toolchain),
            require_shipping_toolchain=require_shipping_toolchain,
        )
        row_shipping_toolchain = batch_row["shipping_path_validation"].get(
            "shipping_toolchain"
        )
        if row_shipping_toolchain is not None:
            if common_shipping_toolchain is None:
                common_shipping_toolchain = row_shipping_toolchain
            elif not _exact_json_value(
                row_shipping_toolchain, common_shipping_toolchain
            ):
                raise RuntimeError(
                    "greedy-tail authority shipping toolchains disagree"
                )
        configs.append(
            GreedyTailConfig(
                batch_capacity=capacity,
                vocab_size=GREEDY_TAIL_VOCAB_SIZE,
                num_threads=int(derived["threads"]),
                num_splits=int(derived["splits"]),
            )
        )
    return tuple(configs)


def _load_greedy_tail_revalidation_evidence(
    path: Path, *, expected_source_keys: frozenset[str]
) -> dict[str, Any]:
    """Load complete prior evidence without accepting stale source authority."""

    if not path.is_file():
        raise RuntimeError(f"missing generated greedy-tail authority: {path}")
    artifact = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(artifact, dict):
        raise RuntimeError("unsupported greedy-tail revalidation evidence")
    source = artifact.get("source")
    if (
        not isinstance(source, Mapping)
        or set(source) != expected_source_keys
        or any(
            not isinstance(value, str)
            or re.fullmatch(r"[0-9a-f]{64}", value) is None
            for value in source.values()
        )
    ):
        raise RuntimeError(
            "greedy-tail revalidation evidence source schema is incomplete"
        )
    validation_copy = copy.deepcopy(artifact)
    validation_copy["source"] = {
        "timing_contract": {
            name: "0" * 64 for name in _B200_TIMING_SOURCE_IDENTITIES
        },
        "shipping_correctness_contract": {
            name: "0" * 64 for name in _SHIPPING_SOURCE_IDENTITIES
        },
    }
    _validate_greedy_tail_artifact(
        validation_copy,
        require_current_sources=False,
        require_shipping_toolchain=False,
    )
    return artifact


@lru_cache(maxsize=1)
def load_greedy_tail_configs(
    path: Path = _AUTHORITY_PATH,
) -> tuple[GreedyTailConfig, ...]:
    if not path.is_file():
        raise RuntimeError(f"missing generated greedy-tail authority: {path}")
    artifact = json.loads(path.read_text(encoding="utf-8"))
    return _validate_greedy_tail_artifact(
        artifact,
        require_current_sources=True,
    )


def greedy_tail_config_for_batch(batch: int) -> GreedyTailConfig | None:
    return next(
        (
            config
            for config in load_greedy_tail_configs()
            if batch <= config.batch_capacity
        ),
        None,
    )


@lru_cache(maxsize=None)
def validate_greedy_tail_shipping_sources(
    path: Path = _AUTHORITY_PATH,
) -> None:
    artifact = json.loads(path.read_text(encoding="utf-8"))
    _validate_greedy_tail_artifact(artifact, require_current_sources=False)
    _validate_shipping_source_identities(artifact["source"])


def greedy_tail_variant_key(vocab_size: int, batch_capacity: int) -> str:
    return f"vocab_{vocab_size}_bf16_greedy_tail_b{batch_capacity}"


_H100_AUTHORITY_PATH = (
    Path(__file__).resolve().parents[1] / "configs" / "greedy_tail_nvidia_h100.json"
)
GREEDY_TAIL_H100_SEARCH_SPACE = GREEDY_TAIL_SEARCH_SPACE
_H100_TIMING_SOURCE_IDENTITIES = frozenset(
    {
        "config_module_sha256",
        "kernel_sha256",
        "runner_sha256",
        "device_compile_contract_sha256",
        "compile_provider_sha256",
        "fake_tensor_provider_sha256",
        "runtime_launch_contract_sha256",
    }
)


def h100_greedy_tail_variant_key(vocab_size: int, batch_capacity: int) -> str:
    return f"vocab_{vocab_size}_bf16_greedy_tail_sm90_b{batch_capacity}"


def _h100_source_paths() -> dict[str, tuple[Path, tuple[str, ...]]]:
    source_root = Path(__file__).resolve().parents[3]
    return {
        "config_module_sha256": (
            Path(__file__),
            _CONFIG_MODULE_IDENTITY_SYMBOLS,
        ),
        "kernel_sha256": (
            Path(__file__).with_name("greedy_tail.py"),
            ("GreedyTail",),
        ),
        "runner_sha256": (
            source_root / "scripts/tune_greedy_tail_h100.py",
            ("_candidate_timing",),
        ),
        "compile_provider_sha256": (
            source_root / "scripts/precompile/families/sampling.py",
            ("_compile_greedy_tail",),
        ),
        "device_compile_contract_sha256": (
            source_root / "scripts/precompile/cubin_bundles.py",
            ("_compile_cubin_device_contract",),
        ),
    }


def _available_h100_source_identities() -> dict[str, dict[str, str]]:
    timing = {
        name: hashlib.sha256(
            semantic_python_symbol_closure_bytes(path, symbols)
        ).hexdigest()
        for name, (path, symbols) in _h100_source_paths().items()
        if path.is_file()
    }
    if _fake_tensor_provider_path() is not None:
        timing["fake_tensor_provider_sha256"] = _fake_tensor_provider_identity()
    timing["runtime_launch_contract_sha256"] = (
        greedy_tail_runtime_launch_contract_sha256()
    )
    return {
        "timing_contract": timing,
        "shipping_correctness_contract": _available_shipping_source_identities(),
    }


def _validate_h100_samples(value: object, *, label: str) -> list[float]:
    if (
        not isinstance(value, list)
        or len(value) != 9
        or any(
            not isinstance(sample, (int, float))
            or isinstance(sample, bool)
            or not math.isfinite(float(sample))
            or float(sample) <= 0.0
            for sample in value
        )
    ):
        raise RuntimeError(f"H100 greedy-tail {label} samples are incomplete")
    return [float(sample) for sample in value]


def _validate_h100_timing(value: object, *, label: str) -> None:
    if not isinstance(value, Mapping) or set(value) != {
        "samples_us",
        "independent_run_samples_us",
        "summary",
    }:
        raise RuntimeError(f"H100 greedy-tail {label} timing is incomplete")
    samples = _validate_h100_samples(value["samples_us"], label=label)
    runs = value["independent_run_samples_us"]
    if (
        not isinstance(runs, list)
        or len(runs) != 9
        or any(
            not isinstance(run, list)
            or len(run) != 3
            or any(
                not isinstance(sample, (int, float))
                or isinstance(sample, bool)
                or not math.isfinite(float(sample))
                or float(sample) <= 0.0
                for sample in run
            )
            for run in runs
        )
    ):
        raise RuntimeError(f"H100 greedy-tail {label} run samples are incomplete")
    independent_runs = [[float(sample) for sample in run] for run in runs]
    if samples != [statistics.median(run) for run in independent_runs]:
        raise RuntimeError(
            f"H100 greedy-tail {label} samples are not raw-run medians"
        )
    if not _exact_json_value(
        value["summary"], derive_greedy_tail_summary(samples)
    ):
        raise RuntimeError(f"H100 greedy-tail {label} summary is not derived")


def _validate_h100_correctness(value: object, *, label: str) -> None:
    if (
        not isinstance(value, Mapping)
        or set(value) != set(GREEDY_TAIL_REQUIRED_CASES)
        or any(result is not True for result in value.values())
    ):
        raise RuntimeError(f"H100 greedy-tail {label} correctness is incomplete")


def _validate_h100_greedy_tail_artifact(
    artifact: object,
    *,
    require_current_sources: bool,
) -> tuple[GreedyTailConfig, ...]:
    if not isinstance(artifact, Mapping) or set(artifact) != {
        "schema_version",
        "target",
        "measurement",
        "source",
        "toolchain",
        "batches",
    }:
        raise RuntimeError("H100 greedy-tail authority is incomplete")
    if artifact["schema_version"] != 1 or not _exact_json_value(
        artifact["target"],
        {
            "gpu": "NVIDIA H100 80GB HBM3",
            "capability": [9, 0],
            "architecture": "sm90",
            "vocab_size": GREEDY_TAIL_VOCAB_SIZE,
            "dtype": "bfloat16",
        },
    ):
        raise RuntimeError("H100 greedy-tail authority target is incomplete")
    measurement = artifact["measurement"]
    if not isinstance(measurement, Mapping) or not _exact_json_value(
        measurement,
        {
            "clock": "CUDA event elapsed time",
            "warmup_launches_per_operation": 200,
            "independent_runs": 9,
            "rounds_per_run": 3,
            "repeats_per_round": 128,
            "randomized_operation_order": True,
            "data_seed": 20260906,
            "measurement_seed_base": 20260906,
        },
    ):
        raise RuntimeError("H100 greedy-tail authority measurement is incomplete")
    source = artifact["source"]
    if (
        not isinstance(source, Mapping)
        or set(source) != _SOURCE_CONTRACT_SECTIONS
    ):
        raise RuntimeError("H100 greedy-tail source identity is incomplete")
    for section, expected in (
        ("timing_contract", _H100_TIMING_SOURCE_IDENTITIES),
        ("shipping_correctness_contract", _SHIPPING_SOURCE_IDENTITIES),
    ):
        values = source[section]
        if (
            not isinstance(values, Mapping)
            or set(values) != expected
            or any(
                not isinstance(value, str)
                or re.fullmatch(r"[0-9a-f]{64}", value) is None
                for value in values.values()
            )
        ):
            raise RuntimeError("H100 greedy-tail source identity is incomplete")
    if require_current_sources:
        available_sources = _available_h100_source_identities()
        if any(
            source["timing_contract"][name] != value
            for name, value in available_sources["timing_contract"].items()
        ):
            raise RuntimeError("H100 greedy-tail authority is stale for current sources")
    toolchain = artifact["toolchain"]
    if (
        not isinstance(toolchain, Mapping)
        or not {"python", "torch", "cuda", "cutlass_dsl", "apache_tvm_ffi"}
        <= set(toolchain)
        or any(not isinstance(value, (str, int)) for value in toolchain.values())
    ):
        raise RuntimeError("H100 greedy-tail toolchain identity is incomplete")
    batches = artifact["batches"]
    if not isinstance(batches, Mapping) or set(batches) != {
        str(batch) for batch in GREEDY_TAIL_BATCH_CAPACITIES
    }:
        raise RuntimeError("H100 greedy-tail batch evidence is incomplete")

    configs = []
    for capacity in GREEDY_TAIL_BATCH_CAPACITIES:
        row = batches[str(capacity)]
        if not isinstance(row, Mapping) or set(row) != {
            "baseline",
            "candidates",
            "selection",
        }:
            raise RuntimeError(
                f"H100 greedy-tail B{capacity} evidence is incomplete"
            )
        baseline = row["baseline"]
        if (
            not isinstance(baseline, Mapping)
            or set(baseline) != {
                "identity",
                "samples_us",
                "independent_run_samples_us",
                "summary",
            }
            or baseline["identity"] != "torch_argmax_plus_index_copy"
        ):
            raise RuntimeError(
                f"H100 greedy-tail B{capacity} baseline is incomplete"
            )
        _validate_h100_timing(
            {name: baseline[name] for name in (
                "samples_us", "independent_run_samples_us", "summary"
            )},
            label=f"B{capacity} baseline",
        )
        candidates = row["candidates"]
        expected = {
            f"t{threads}_s{splits}": (threads, splits)
            for threads, splits in GREEDY_TAIL_H100_SEARCH_SPACE[capacity]
        }
        if not isinstance(candidates, Mapping) or set(candidates) != set(expected):
            raise RuntimeError(
                f"H100 greedy-tail B{capacity} candidate coverage is incomplete"
            )
        for identity, (threads, splits) in expected.items():
            candidate = candidates[identity]
            if (
                not isinstance(candidate, Mapping)
                or set(candidate) != {
                    "threads",
                    "splits",
                    "correctness",
                    "samples_us",
                    "independent_run_samples_us",
                    "summary",
                }
                or candidate["threads"] != threads
                or candidate["splits"] != splits
            ):
                raise RuntimeError(
                    f"H100 greedy-tail B{capacity} candidate {identity} is incomplete"
                )
            _validate_h100_correctness(
                candidate["correctness"], label=f"B{capacity} {identity}"
            )
            _validate_h100_timing(
                {name: candidate[name] for name in (
                    "samples_us", "independent_run_samples_us", "summary"
                )},
                label=f"B{capacity} {identity}",
            )
        selection = derive_greedy_tail_selection(candidates)
        if not _exact_json_value(row["selection"], selection):
            raise RuntimeError(
                f"H100 greedy-tail B{capacity} selection is not derived"
            )
        if selection["median_us"] >= baseline["summary"]["median_us"]:
            raise RuntimeError(
                f"H100 greedy-tail B{capacity} does not beat torch"
            )
        configs.append(
            GreedyTailConfig(
                batch_capacity=capacity,
                vocab_size=GREEDY_TAIL_VOCAB_SIZE,
                num_threads=int(selection["threads"]),
                num_splits=int(selection["splits"]),
            )
        )
    return tuple(configs)


@lru_cache(maxsize=1)
def load_h100_greedy_tail_configs(
    path: Path = _H100_AUTHORITY_PATH,
) -> tuple[GreedyTailConfig, ...]:
    if not path.is_file():
        raise RuntimeError(f"missing generated H100 greedy-tail authority: {path}")
    return _validate_h100_greedy_tail_artifact(
        json.loads(path.read_text(encoding="utf-8")),
        require_current_sources=True,
    )


def h100_greedy_tail_config_for_batch(batch: int) -> GreedyTailConfig | None:
    return next(
        (
            config
            for config in load_h100_greedy_tail_configs()
            if batch <= config.batch_capacity
        ),
        None,
    )


@lru_cache(maxsize=None)
def validate_h100_greedy_tail_shipping_sources(
    path: Path = _H100_AUTHORITY_PATH,
) -> None:
    artifact = json.loads(path.read_text(encoding="utf-8"))
    _validate_h100_greedy_tail_artifact(artifact, require_current_sources=False)
    _validate_shipping_source_identities(artifact["source"])


@dataclass(frozen=True)
class AmpereGreedyTailTarget:
    """Exact device identity for one generated Ampere authority."""

    key: str
    gpu: str
    capability: tuple[int, int]
    architecture: str
    num_sms: int

    @property
    def authority_filename(self) -> str:
        return f"greedy_tail_ampere_{self.key}.json"


class AmpereGreedyTailCalibrationUnavailable(RuntimeError):
    """No generated authority exists for one exact Ampere target."""


GREEDY_TAIL_AMPERE_SEARCH_SPACE = GREEDY_TAIL_SEARCH_SPACE
_AMPERE_CAPABILITIES = frozenset({(8, 0), (8, 6), (8, 7)})
_AMPERE_TIMING_SOURCE_IDENTITIES = frozenset(
    {
        "config_module_sha256",
        "kernel_sha256",
        "runner_sha256",
        "common_runner_provider_sha256",
        "device_compile_contract_sha256",
        "compile_provider_sha256",
        "fake_tensor_provider_sha256",
        "runtime_launch_contract_sha256",
        "target_identity_provider_sha256",
    }
)


def ampere_greedy_tail_target_for_device(
    gpu: str,
    capability: tuple[int, int],
    num_sms: int,
) -> AmpereGreedyTailTarget | None:
    from kestrel_kernels.arch import normalize_gpu_name_key

    if (
        not isinstance(gpu, str)
        or not gpu
        or not isinstance(capability, tuple)
        or len(capability) != 2
        or any(type(value) is not int for value in capability)
        or capability not in _AMPERE_CAPABILITIES
        or type(num_sms) is not int
        or num_sms <= 0
    ):
        return None
    return AmpereGreedyTailTarget(
        key=(
            f"{normalize_gpu_name_key(gpu)}_"
            f"cc{capability[0]}{capability[1]}_sms{num_sms}"
        ),
        gpu=gpu,
        capability=capability,
        architecture=f"sm{capability[0]}{capability[1]}",
        num_sms=num_sms,
    )


def ampere_greedy_tail_variant_key(
    vocab_size: int,
    batch_capacity: int,
    target_key: str,
) -> str:
    if re.fullmatch(r"[a-z0-9]+(?:_[a-z0-9]+)*", target_key) is None:
        raise ValueError(f"invalid Ampere greedy-tail target key {target_key!r}")
    return (
        f"vocab_{vocab_size}_bf16_greedy_tail_"
        f"{target_key}_b{batch_capacity}"
    )


def _ampere_source_paths() -> dict[str, tuple[Path, tuple[str, ...]]]:
    source_root = Path(__file__).resolve().parents[3]
    return {
        "config_module_sha256": (
            Path(__file__),
            _CONFIG_MODULE_IDENTITY_SYMBOLS,
        ),
        "kernel_sha256": (
            Path(__file__).with_name("greedy_tail.py"),
            ("GreedyTail",),
        ),
        "runner_sha256": (
            source_root / "scripts/tune_greedy_tail_ampere.py",
            ("_candidate_timing",),
        ),
        "common_runner_provider_sha256": (
            source_root / "scripts/tune_greedy_tail.py",
            (
                "_atomic_write",
                "_correctness_gate",
                "_make_context",
                "_measure_independent",
                "_raw_operation",
                "_toolchain_identity",
                "_torch_operation",
            ),
        ),
        "device_compile_contract_sha256": (
            source_root / "scripts/precompile/cubin_bundles.py",
            ("_compile_cubin_device_contract",),
        ),
        "compile_provider_sha256": (
            source_root / "scripts/precompile/families/sampling.py",
            ("_compile_greedy_tail",),
        ),
        "runtime_launch_contract_sha256": (
            Path(__file__).resolve().parents[1] / "cubin_runtime.py",
            _RUNTIME_LAUNCH_CONTRACT_IDENTITY_SYMBOLS,
        ),
        "target_identity_provider_sha256": (
            Path(__file__).resolve().parents[1] / "arch.py",
            ("normalize_gpu_name_key",),
        ),
    }


def _available_ampere_source_identities() -> dict[str, dict[str, str]]:
    timing = {
        name: hashlib.sha256(
            semantic_python_symbol_closure_bytes(path, symbols)
        ).hexdigest()
        for name, (path, symbols) in _ampere_source_paths().items()
        if path.is_file()
    }
    if _fake_tensor_provider_path() is not None:
        timing["fake_tensor_provider_sha256"] = _fake_tensor_provider_identity()
    return {
        "timing_contract": timing,
        "shipping_correctness_contract": _available_shipping_source_identities(),
    }


def _validate_ampere_greedy_tail_artifact(
    artifact: object,
    *,
    target: AmpereGreedyTailTarget | None,
    require_current_sources: bool,
) -> tuple[GreedyTailConfig, ...]:
    if not isinstance(artifact, Mapping):
        raise RuntimeError("Ampere greedy-tail authority is incomplete")
    raw_target = artifact.get("target")
    if not isinstance(raw_target, Mapping):
        raise RuntimeError("Ampere greedy-tail authority target is incomplete")
    try:
        artifact_target = ampere_greedy_tail_target_for_device(
            raw_target["gpu"],
            tuple(raw_target["capability"]),
            raw_target["num_sms"],
        )
    except (KeyError, TypeError):
        artifact_target = None
    if artifact_target is None:
        raise RuntimeError("Ampere greedy-tail authority target is incomplete")
    if not _exact_json_value(
        raw_target,
        {
            "key": artifact_target.key,
            "gpu": artifact_target.gpu,
            "capability": list(artifact_target.capability),
            "architecture": artifact_target.architecture,
            "num_sms": artifact_target.num_sms,
            "vocab_size": GREEDY_TAIL_VOCAB_SIZE,
            "dtype": "bfloat16",
        },
    ) or (target is not None and artifact_target != target):
        raise RuntimeError("Ampere greedy-tail authority target is incomplete")
    source = artifact.get("source")
    if (
        not isinstance(source, Mapping)
        or set(source) != _SOURCE_CONTRACT_SECTIONS
    ):
        raise RuntimeError("Ampere greedy-tail source identity is incomplete")
    for section, expected in (
        ("timing_contract", _AMPERE_TIMING_SOURCE_IDENTITIES),
        ("shipping_correctness_contract", _SHIPPING_SOURCE_IDENTITIES),
    ):
        values = source[section]
        if (
            not isinstance(values, Mapping)
            or set(values) != expected
            or any(
                not isinstance(value, str)
                or re.fullmatch(r"[0-9a-f]{64}", value) is None
                for value in values.values()
            )
        ):
            raise RuntimeError("Ampere greedy-tail source identity is incomplete")
    if require_current_sources:
        available_sources = _available_ampere_source_identities()
        if any(
            source["timing_contract"][name] != value
            for name, value in available_sources["timing_contract"].items()
        ):
            raise RuntimeError(
                "Ampere greedy-tail authority is stale for current sources"
            )
    # The legacy H100 validator already owns the common evidence schema and
    # complete derivation checks. Validate an exact projection through it so
    # Ampere targets cannot drift into a second, weaker evidence format while
    # leaving the H100 authority and its source fingerprint untouched.
    structural = dict(artifact)
    structural["source"] = {
        "timing_contract": {
            name: source["timing_contract"][name]
            for name in _H100_TIMING_SOURCE_IDENTITIES
        },
        "shipping_correctness_contract": dict(
            source["shipping_correctness_contract"]
        ),
    }
    structural["target"] = {
        "gpu": "NVIDIA H100 80GB HBM3",
        "capability": [9, 0],
        "architecture": "sm90",
        "vocab_size": GREEDY_TAIL_VOCAB_SIZE,
        "dtype": "bfloat16",
    }
    return _validate_h100_greedy_tail_artifact(
        structural,
        require_current_sources=False,
    )


@lru_cache(maxsize=None)
def load_ampere_greedy_tail_configs(
    target: AmpereGreedyTailTarget,
    path: Path | None = None,
) -> tuple[GreedyTailConfig, ...]:
    authority_path = (
        Path(__file__).resolve().parents[1] / "configs" / target.authority_filename
        if path is None
        else Path(path)
    )
    if not authority_path.is_file():
        raise AmpereGreedyTailCalibrationUnavailable(
            f"missing generated Ampere greedy-tail authority: {authority_path}"
        )
    return _validate_ampere_greedy_tail_artifact(
        json.loads(authority_path.read_text(encoding="utf-8")),
        target=target,
        require_current_sources=True,
    )


@lru_cache(maxsize=None)
def validate_ampere_greedy_tail_shipping_sources(
    target: AmpereGreedyTailTarget, path: Path | None = None
) -> None:
    authority = (
        Path(__file__).resolve().parents[1] / "configs" / target.authority_filename
        if path is None
        else Path(path)
    )
    artifact = json.loads(authority.read_text(encoding="utf-8"))
    _validate_ampere_greedy_tail_artifact(
        artifact, target=target, require_current_sources=False
    )
    _validate_shipping_source_identities(artifact["source"])


def ampere_greedy_tail_config_for_batch(
    batch: int,
    target: AmpereGreedyTailTarget,
) -> GreedyTailConfig | None:
    return next(
        (
            config
            for config in load_ampere_greedy_tail_configs(target)
            if batch <= config.batch_capacity
        ),
        None,
    )


def _discover_ampere_greedy_tail_targets(
    config_dir: Path | None = None,
    *,
    require_current_sources: bool,
) -> dict[str, AmpereGreedyTailTarget]:
    root = (
        Path(__file__).resolve().parents[1] / "configs"
        if config_dir is None
        else Path(config_dir)
    )
    targets = {}
    for path in sorted(root.glob("greedy_tail_ampere_*.json")):
        if path.is_symlink() or not path.is_file():
            raise RuntimeError(f"invalid generated Ampere authority path: {path}")
        artifact = json.loads(path.read_text(encoding="utf-8"))
        raw_target = artifact.get("target") if isinstance(artifact, Mapping) else None
        try:
            target = ampere_greedy_tail_target_for_device(
                raw_target["gpu"],
                tuple(raw_target["capability"]),
                raw_target["num_sms"],
            )
        except (KeyError, TypeError):
            target = None
        if target is None or path.name != target.authority_filename:
            raise RuntimeError(f"invalid generated Ampere authority path: {path}")
        _validate_ampere_greedy_tail_artifact(
            artifact,
            target=target,
            require_current_sources=require_current_sources,
        )
        if target.key in targets:
            raise RuntimeError(
                f"duplicate generated Ampere greedy-tail target {target.key!r}"
            )
        targets[target.key] = target
    return targets


def discover_ampere_greedy_tail_targets(
    config_dir: Path | None = None,
) -> dict[str, AmpereGreedyTailTarget]:
    """Discover valid authorities that are current runtime inputs."""

    return _discover_ampere_greedy_tail_targets(
        config_dir,
        require_current_sources=True,
    )


def discover_ampere_greedy_tail_inventory_targets(
    config_dir: Path | None = None,
) -> dict[str, AmpereGreedyTailTarget]:
    """Discover structurally valid targets for cross-architecture inventory.

    Inventory declaration needs stable variant identities for every packaged
    target, but it does not consume their measured selections. The target
    architecture's materializer still validates current source identities
    before compiling any calibrated variant.
    """

    return _discover_ampere_greedy_tail_targets(
        config_dir,
        require_current_sources=False,
    )


